t; // overwriting existing important\n\n                }\n                @media (max-width: $large) {\n                    &:first-of-type {\n                        background: $green-3;\n                    }\n                }\n                @media (max-width: $modal-medium) {\n                    font-size: 16px;\n                }\n            }\n        }\n    }\n}\n.dk-loading-button {\n    font-size: 22px;\n    .divider {\n        display: inline-block;\n        padding: 0px 4px 0px 4px;\n        font-size: 22px;\n        @media (max-width: $modal-medium) {\n            font-size: 16px;\n        }\n    }\n    @media (max-width: $modal-medium) {\n        font-size: 16px;\n    }\n}\n.spinner {\n    display: inline-block;\n    font-size: 22px;\n    position: relative;\n    text-indent: -9999em;\n    border: 4px solid rgba(255, 255, 255, 0.2);\n    border-left: 4px solid $white;\n    margin-top: 4px;\n    transform: translateZ(0);\n    animation: spin 1s infinite cubic-bezier(0.24, 0.31, 0.6, 0.21);\n    display: inline-block !important;\n    @media (max-width: $modal-medium) {\n        font-size: 16px;\n        margin-top: 2px;\n    }\n    &, &:after {\n        border-radius: 50%;\n        width: 18px;\n        height: 18px;\n    }\n}\n@keyframes spin {\n    0% {\n        transform: rotate(0deg);\n    }\n    100% {\n        transform: rotate(360deg);\n    }\n}\n.clear {\n    clear: both;\n}\n","//\n// COLORS\n//\n\n// basic\n$black: #000;\n$white: #fff;\n\n// red\n$red-1: #ff8c69; // lightest\n$red-2: #ff4d44;\n$red-3: #e9344a;\n$red-4: #cc192a;\n$red-5: #990025; //darkest\n$red-6: #b81427;\n\n// orange\n$orange-1: #ffa842; // lightest\n$orange-2: #ff890b;\n$orange-3: #ff6c00;\n$orange-4: #f3601b;\n$orange-5: #bf4400; // darkest\n\n// gold\n$gold-1: #ffe555; // lightest\n$gold-2: #ffd20d;\n$gold-3: #f3b700;\n$gold-4: #db9000;\n$gold-5: #c47d00; // darkest\n$gold-6: #f7d002;\n\n// green\n$green-1: #9ae200; // lightest\n$green-2: #79c600;\n$green-3: #5ea600;\